import React, { useState } from 'react';
import './estilos.css';

export default function App() {
  const [user, setUser] = useState({
    name: 'Carlos Silva',
    xp: 450,
    level: 3,
    badges: [
      { id: 1, title: 'Guardião da Senha', icon: '🛡️', description: 'Criou uma senha forte e ativou 2FA.' },
      { id: 2, title: 'Caçador de Phishing', icon: '🎣', description: 'Identificou e reportou um e-mail suspeito.' }
    ]
  });

  return (
    <div style={{ padding: '30px', fontFamily: 'Arial, sans-serif', backgroundColor: '#0f172a', color: '#fff', minHeight: '100vh' }}>
      <header style={{ marginBottom: '30px', borderBottom: '1px solid #334155', paddingBottom: '15px' }}>
        <h1 style={{ margin: 0, color: '#38bdf8' }}>🔒 Painel Gamificado de Segurança</h1>
        <p style={{ color: '#94a3b8', margin: '5px 0 0 0' }}>Bem-vindo de volta, {user.name}!</p>
      </header>

      <div style={{ display: 'flex', gap: '20px', marginBottom: '30px' }}>
        <div style={{ background: '#1e293b', padding: '20px', borderRadius: '8px', flex: 1 }}>
          <h3 style={{ margin: '0 0 10px 0', color: '#f8fafc' }}>Nível Atual</h3>
          <p style={{ fontSize: '24px', fontWeight: 'bold', color: '#34d399', margin: 0 }}>Nível {user.level}</p>
        </div>
        <div style={{ background: '#1e293b', padding: '20px', borderRadius: '8px', flex: 1 }}>
          <h3 style={{ margin: '0 0 10px 0', color: '#f8fafc' }}>Experiência (XP)</h3>
          <p style={{ fontSize: '24px', fontWeight: 'bold', color: '#fbbf24', margin: 0 }}>{user.xp} XP</p>
        </div>
      </div>

      <section style={{ background: '#1e293b', padding: '20px', borderRadius: '8px' }}>
        <h2 style={{ marginTop: 0, color: '#f8fafc' }}>As suas Conquistas</h2>
        <ul style={{ listStyle: 'none', padding: 0, margin: 0 }}>
          {user.badges.map(badge => (
            <li key={badge.id} style={{ display: 'flex', alignItems: 'center', padding: '10px 0', borderBottom: '1px solid #334155' }}>
              <span style={{ fontSize: '24px', marginRight: '15px' }}>{badge.icon}</span>
              <div>
                <strong style={{ color: '#e2e8f0' }}>{badge.title}</strong>
                <p style={{ margin: '2px 0 0 0', color: '#94a3b8', fontSize: '14px' }}>{badge.description}</p>
              </div>
            </li>
          ))}
        </ul>
      </section>
    </div>
  );
}
